# Illustration du complément à 2 sur 8 bits
def complement_a_deux(n, nb_bits=8):
    if n >= 0:
        return bin(n)
    return bin((1 << nb_bits) + n)

print('5  :', complement_a_deux(5))    # positif
print('-5 :', complement_a_deux(-5))   # négatif en complément à 2
print('-1 :', complement_a_deux(-1))   # vaut 1111 1111

