def search(x, y):
    for i in range(len(y)):
        if x == y[i]:
            return i
    return None

import time
for n in [1000, 10000, 100000]:
    y = list(range(n))
    t = time.time()
    search(n-1, y)  # pire cas : chercher le dernier élément
